      ]
    },
    {
      "id": "F6",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The Joint Chiefs favored leaving intelligence responsibilities with existing departments rather than assigning them generally to a central agency.",
      "spans": [
        "src:57ef32c7931d#p3.1"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
